NS_IMETHODIMP ExchangeService::GetUrlForUri(const nsACString& aMessageURI,
                                            nsIMsgWindow* aMsgWindow,
                                            nsIURI** _retval) {
  nsCOMPtr<nsIURI> messageURI;
  MOZ_TRY(NS_NewURI(getter_AddRefs(messageURI), aMessageURI));

  nsAutoCString scheme;
  MOZ_TRY(messageURI->GetScheme(scheme));

  // If the URI is already an "x-moz-{ews,graph}" URI, forward it as-is.
  if (scheme.Equals("x-moz-ews") || scheme.Equals("x-moz-graph")) {
    messageURI.forget(_retval);
    return NS_OK;
  }

  // At this point, the path to the message URI is expected to look like
  // /Path/To/Folder#MessageKey. With this format, if the user switches between
  // messages in the same folder, the docshell believes we're still in the same
  // document (because only the fragment/ref changed), and skips creating a
  // channel for any message except the first one. So we need to transform the
  // path into /Path/To/Folder/MessageKey.
  nsAutoCString ref;
  nsresult rv = messageURI->GetRef(ref);
  NS_ENSURE_SUCCESS(rv, rv);

  nsCString path;
  rv = messageURI->GetFilePath(path);
  NS_ENSURE_SUCCESS(rv, rv);
  path.Append("/");
  path.Append(ref);

  nsCString query;
  rv = messageURI->GetQuery(query);
  NS_ENSURE_SUCCESS(rv, rv);

  nsAutoCString channelScheme;
  if (scheme.EqualsLiteral("ews-message")) {
    channelScheme.Assign("x-moz-ews");
  } else if (scheme.EqualsLiteral("graph-message")) {
    channelScheme.Assign("x-moz-graph");
  }

  if (channelScheme.IsEmpty()) {
    MOZ_LOG_FMT(gExchangeLog, mozilla::LogLevel::Error,
                "Unknown message URI scheme: %s", scheme);
    return NS_ERROR_UNEXPECTED;
  }

  // "x-moz-{ews,graph}" is the scheme we use for URIs that must be used for
  // channels opened via a protocol handler consumer (such as a docshell or the
  // I/O service). These channels are expected to serve the raw content RFC822
  // content of the message referred to by the URI.
  return NS_MutateURI(messageURI)
      .SetScheme(channelScheme)
      .SetPathQueryRef(path)
      .SetQuery(query)
      .Finalize(_retval);
}
